:root {
  --bg: #080c11;
  --panel: rgba(15, 21, 29, .94);
  --panel-soft: rgba(20, 28, 38, .82);
  --line: rgba(151, 169, 185, .12);
  --line-strong: rgba(151, 169, 185, .22);
  --text: #edf3f3;
